import React, { useState, useEffect } from 'react';
import Header from './pages/header/header';
import Inicio from './pages/inicio/Inicio';
import About from './pages/about/about';
import Services from './pages/services/services';
import Projects from './pages/projects/projects';
import Contact from './pages/contact/contact';
import Footer from './components/footer/Footer';
import ServiceRefrigeracion from './pages/services/ServiceRefrigeracion';
import ServiceSistemas from './pages/services/ServiceSistemas';
import ServiceElectricidad from './pages/services/ServiceElectricidad';
import PoliticaPrivacidad from './pages/privacidad/PoliticaPrivacidad';

import WhyChooseUs from './components/whychooseus/WhyChooseUs';

import CotizadorElectricidadModal from './components/cotizador/CotizadorElectricidadModal';
import FaqChatbot from './components/chatbot/FaqChatbot';

function App() {
  const [isCotizadorOpen, setIsCotizadorOpen] = useState(false);
  const [hash, setHash] = useState(() => {
    const currentHash = window.location.hash;
    if (!currentHash || currentHash === '#inicio') {
      return '#inicio';
    }
    return currentHash;
  });

  useEffect(() => {
    // Si carga con #inicio, limpiamos la URL de inmediato para estética
    if (window.location.hash === '#inicio') {
      window.history.replaceState({}, document.title, window.location.pathname);
    }

    const handleHashChange = () => {
      const currentHash = window.location.hash;
      if (!currentHash || currentHash === '#inicio') {
        if (window.location.hash === '#inicio') {
          window.history.replaceState({}, document.title, window.location.pathname);
        }
        setHash('#inicio');
      } else {
        setHash(currentHash);
      }
    };
    // Evento personalizado del header para navegación directa y confiable
    const handleMitNavigate = (e: Event) => {
      const id = (e as CustomEvent).detail;
      setHash('#' + id);
    };
    window.addEventListener('hashchange', handleHashChange);
    window.addEventListener('mitNavigate', handleMitNavigate);
    return () => {
      window.removeEventListener('hashchange', handleHashChange);
      window.removeEventListener('mitNavigate', handleMitNavigate);
    };
  }, []);

  const isAboutFull = hash === '#acerca';
  const isServRefrig = hash === '#servicio-refrigeracion' || hash === '#refrigeracion';
  const isServSistemas = hash === '#servicio-sistemas' || hash === '#sistemas-informaticos' || hash === '#sistemas';
  const isServElec = hash === '#servicio-electricidad' || hash === '#electricidad';
  const isPrivacidad = hash === '#privacidad';
  const isFullPage = isAboutFull || isServRefrig || isServSistemas || isServElec || isPrivacidad;

  // Desplazamiento suave al cambiar de hash en la página principal
  useEffect(() => {
    if (isFullPage) {
      window.scrollTo({ top: 0, behavior: 'auto' });
      return;
    }

    const currentHash = hash.replace('#', '');
    if (currentHash && currentHash !== 'inicio' && currentHash !== 'acerca') {
      const timer = setTimeout(() => {
        const element = document.getElementById(currentHash);
        if (element) {
          const headerOffset = 90;
          const elementPosition = element.getBoundingClientRect().top;
          const offsetPosition = elementPosition + window.scrollY - headerOffset;
          window.scrollTo({
            top: offsetPosition,
            behavior: 'smooth'
          });
        }
      }, 120);
      return () => clearTimeout(timer);
    } else if (currentHash === 'inicio') {
      window.scrollTo({ top: 0, behavior: 'smooth' });
    }
  }, [hash, isFullPage]);

  const renderFullPage = () => {
    if (isAboutFull) return <About isFull={true} />;
    if (isServRefrig) return <ServiceRefrigeracion />;
    if (isServSistemas) return <ServiceSistemas />;
    if (isServElec) return <ServiceElectricidad onOpenCotizador={() => setIsCotizadorOpen(true)} />;
    if (isPrivacidad) return <PoliticaPrivacidad />;
    return null;
  };

  return (
    <div className="App">
      <style>
        {`
          *, *::before, *::after {
            box-sizing: border-box;
          }
          html {
            scroll-behavior: smooth;
            overflow-x: hidden;
            width: 100%;
          }
          @import url('https://fonts.googleapis.com/css2?family=Inter:wght@300;400;500;600;700;800&display=swap');
          body {
            margin: 0;
            background-color: #f8f9fa;
            font-family: 'Inter', sans-serif;
            overflow-x: hidden;
            width: 100%;
          }

          /* --- Personalización de la barra de desplazamiento (Scrollbar) --- */
          ::-webkit-scrollbar {
            width: 12px; /* Grosor de la barra */
          }
          ::-webkit-scrollbar-track {
            background: #F8FAFC; /* Fondo del carril */
          }
          ::-webkit-scrollbar-thumb {
            background: #CBD5E1; /* Color de la barra inactiva */
            border-radius: 10px;
            border: 3px solid #F8FAFC; /* Crea un efecto de padding interior */
          }
          ::-webkit-scrollbar-thumb:hover {
            background: #3B82F6; /* Azul corporativo al pasar el ratón */
          }

          /* Transición de entrada premium para las secciones */
          .section-fade {
            animation: fadeInSection 0.45s cubic-bezier(0.16, 1, 0.3, 1) forwards;
          }
          @keyframes fadeInSection {
            from {
              opacity: 0;
              transform: translateY(12px);
            }
            to {
              opacity: 1;
              transform: translateY(0);
            }
          }
        `}
      </style>
      <Header />
      
      {isFullPage ? (
        <div key={hash} className="section-fade">
          {renderFullPage()}
        </div>
      ) : (
        <div key="main-page" className="section-fade">
          <Inicio />
          <About isFull={false} />
          <WhyChooseUs />
          <Services />
          <Projects />
          <Contact />
        </div>
      )}
      <Footer />

      {/* Modal Cotizador de Electricidad */}
      <CotizadorElectricidadModal
        isOpen={isCotizadorOpen}
        onClose={() => setIsCotizadorOpen(false)}
      />

      {/* Chatbot de Preguntas Frecuentes */}
      <FaqChatbot onOpenCotizador={() => setIsCotizadorOpen(true)} />
    </div>
  );
}

export default App;

